-- Read-only baseline extracted from TESTE on 2026-08-13.
-- Source: Resultado_da_Query (24).xlsx; do not edit as deployment source.
CREATE OR REPLACE PROCEDURE STP_VALIDAFAT_FILARES_PRA(P_NUNOTA INT, P_SEQUENCIA INT, P_QTDENTREGUE NUMBER, V_ACAO VARCHAR2) AS

PRAGMA AUTONOMOUS_TRANSACTION;

V_SALDO    NUMBER;
V_FATSEQ  NUMBER;
V_DESCRPROD  TGFPRO.DESCRPROD%TYPE;
V_VALIDA  NUMBER;
BEGIN


/* Alteração 25/02/2025 (Chamado #T2502-407) : Não considerar validação de faturamento de pedido direto para nota */
SELECT
COUNT(*)
INTO
V_VALIDA
FROM
TGFCAB CAB
INNER JOIN TGFTOP TOP ON
TOP.CODTIPOPER = CAB.CODTIPOPER
AND TOP.DHALTER = CAB.DHTIPOPER
WHERE
NUNOTA = P_NUNOTA
--AND TOP.GRUPO = 'Vendas'
AND TOP.CODTIPOPER = 906;
IF V_VALIDA > 0 THEN
RETURN;
END IF;

/* Fim alteração */

--busca a quantidade calculada na fila, podendo ser parcial (1 X N)
V_SALDO := 0;

FOR I IN (
SELECT RES.SALDO
, RES.QTDPENDENTE
, RES.AD_SEQRESERVA
FROM AD_VGFRESEST RES
WHERE RES.NUNOTA = P_NUNOTA
AND RES.SEQUENCIA = P_SEQUENCIA
)
LOOP
--se o saldo atende a quantidade faturada
IF I.SALDO > 0 THEN  -- inclusaod do OR V_ACAO = 'DELETE'
V_SALDO := NVL(V_SALDO,0) + I.QTDPENDENTE;

UPDATE AD_TGFSEQENT E
SET E.QTDENTREGUE = NVL(E.QTDENTREGUE,0) +  I.QTDPENDENTE
WHERE E.SEQENT = I.AD_SEQRESERVA
AND E.NUNOTA = P_NUNOTA
AND E.SEQUENCIA = P_SEQUENCIA;

IF V_SALDO = P_QTDENTREGUE THEN
EXIT;
END IF;

ELSIF (I.SALDO + I.QTDPENDENTE) > 0 THEN

V_SALDO :=  NVL(V_SALDO,0) + (I.QTDPENDENTE + I.SALDO);

UPDATE AD_TGFSEQENT E
SET E.QTDENTREGUE = NVL(E.QTDENTREGUE,0) + (I.QTDPENDENTE + I.SALDO)
WHERE E.SEQENT = I.AD_SEQRESERVA
AND E.NUNOTA = P_NUNOTA
AND E.SEQUENCIA = P_SEQUENCIA;

--se o saldo nao atende a quantidade faturada
ELSE V_SALDO := I.SALDO;
END IF;

END LOOP;


/* NOVO BLOCO PARA TRATAR CANCELAMENTO E EXCLUSAOA DE NOTAS */
IF V_ACAO = 'DELETE' THEN
FOR I IN (SELECT *
FROM AD_TGFSEQENT
WHERE NUNOTA = P_NUNOTA AND SEQUENCIA = P_SEQUENCIA)
LOOP
UPDATE AD_TGFSEQENT E
SET E.QTDENTREGUE = NVL(E.QTDENTREGUE,0) +  P_QTDENTREGUE
WHERE E.SEQENT = I.SEQENT
AND E.NUNOTA = P_NUNOTA
AND E.SEQUENCIA = P_SEQUENCIA;

IF V_SALDO = P_QTDENTREGUE THEN
EXIT;
END IF;
END LOOP;
END IF;


IF P_QTDENTREGUE > V_SALDO THEN

SELECT PRO.CODPROD||'-'||PRO.DESCRPROD
INTO V_DESCRPROD
FROM TGFITE ITE
JOIN TGFPRO PRO ON ITE.CODPROD = PRO.CODPROD
WHERE ITE.SEQUENCIA = P_SEQUENCIA
AND ITE.NUNOTA = P_NUNOTA;

BEGIN
UPDATE AD_TGFSEQENT
SET  QTDENTREGUE = (SELECT I.QTDENTREGUE FROM TGFITE I WHERE I.NUNOTA = AD_TGFSEQENT.NUNOTA AND I.PENDENTE = 'S' AND I.SEQUENCIA = AD_TGFSEQENT.SEQUENCIA)
WHERE  NUNOTA = P_NUNOTA
AND nvl(qtdentregue,0) <> 0
AND NUNOTA IN  (SELECT I.NUNOTA FROM TGFITE I WHERE I.NUNOTA = AD_TGFSEQENT.NUNOTA AND I.PENDENTE = 'S' AND I.SEQUENCIA = AD_TGFSEQENT.SEQUENCIA);

COMMIT;
END;

STP_MSGERRO_SNK('Erro ao gerar faturamento.'
,'O item <b>'||V_DESCRPROD||'</b> do pedido <b>'||P_NUNOTA ||'</b> consta na fila de reserva de estoque, e o saldo disponivel para esse item é de '||V_SALDO|| ' e a quantidade faturada é de '||P_QTDENTREGUE
,'Fature uma quantidade possivel ou negocie sua posição na fila'
);
ROLLBACK ;

END IF;

COMMIT;


END STP_VALIDAFAT_FILARES_PRA;

/
